CREATE TABLE "accounts" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)));
CREATE TABLE "budget_moves" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "year" INTEGER NOT NULL, "month" INTEGER NOT NULL, "from_category_id" INTEGER NOT NULL REFERENCES categories (id) ON DELETE CASCADE, "to_category_id" INTEGER NOT NULL REFERENCES categories (id) ON DELETE CASCADE, "amount" INTEGER NOT NULL, "date" INTEGER NOT NULL, "note" TEXT NOT NULL DEFAULT '');
CREATE TABLE "budgets" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "year" INTEGER NOT NULL, "month" INTEGER NOT NULL, "category_id" INTEGER NOT NULL REFERENCES categories (id), "amount" INTEGER NOT NULL, UNIQUE ("year", "month", "category_id"));
CREATE TABLE "categories" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "parent_id" INTEGER NULL REFERENCES categories (id), "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "is_fixed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_fixed" IN (0, 1)), "due_day" INTEGER NULL, "savings_fund_id" INTEGER NULL REFERENCES funds (id), "slot_year" INTEGER NULL, "slot_month" INTEGER NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)));
CREATE TABLE "entries" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "date" INTEGER NOT NULL, "type" TEXT NOT NULL, "amount" INTEGER NOT NULL, "category_id" INTEGER NULL REFERENCES categories (id), "loan_id" INTEGER NULL REFERENCES loans (id), "tracker_id" INTEGER NULL, "note" TEXT NOT NULL DEFAULT '', "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "receipt" TEXT NULL);
CREATE TABLE "funds" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "target_amount" INTEGER NULL, "target_date" INTEGER NULL, "achieved_at" INTEGER NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)));
CREATE TABLE "investment_details" ("account_id" INTEGER NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "kind" TEXT NOT NULL, "start_date" INTEGER NULL, "maturity_date" INTEGER NULL, "rate_bp" INTEGER NULL, "instalment" INTEGER NULL, "total_instalments" INTEGER NULL, "opening_instalments" INTEGER NOT NULL DEFAULT 0, "note" TEXT NOT NULL DEFAULT '', PRIMARY KEY ("account_id"));
CREATE TABLE "loans" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "kind" TEXT NOT NULL, "person_account_id" INTEGER NULL REFERENCES accounts (id), "fund_id" INTEGER NOT NULL REFERENCES funds (id), "principal" INTEGER NOT NULL, "charge_rate_bp" INTEGER NOT NULL DEFAULT 0, "charge" INTEGER NOT NULL DEFAULT 0, "opening_repaid" INTEGER NOT NULL DEFAULT 0, "date" INTEGER NOT NULL, "due_date" INTEGER NULL, "note" TEXT NOT NULL DEFAULT '', "closed_at" INTEGER NULL);
CREATE TABLE "month_closes" ("year" INTEGER NOT NULL, "month" INTEGER NOT NULL, "closed_at" INTEGER NOT NULL, "confirmed_bank" INTEGER NULL, PRIMARY KEY ("year", "month"));
CREATE TABLE "postings" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "entry_id" INTEGER NOT NULL REFERENCES entries (id) ON DELETE CASCADE, "account_id" INTEGER NOT NULL REFERENCES accounts (id), "fund_id" INTEGER NOT NULL REFERENCES funds (id), "amount" INTEGER NOT NULL);
CREATE TABLE "purchases" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "entry_id" INTEGER NULL REFERENCES entries (id) ON DELETE CASCADE, "item" TEXT NOT NULL, "date" INTEGER NOT NULL, "amount" INTEGER NOT NULL, "shop" TEXT NOT NULL DEFAULT '', "warranty_until" INTEGER NULL, "note" TEXT NOT NULL DEFAULT '');
CREATE TABLE "settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "trackers" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "budget" INTEGER NULL, "opening_spent" INTEGER NOT NULL DEFAULT 0, "start_date" INTEGER NOT NULL, "end_date" INTEGER NULL, "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)));
